mapper.update:
UPDATE invoice
invoice_no = #{invoiceNo}, invoice_date = #{invoiceDate}, total_amount = #{totalAmount}, file_url = #{fileUrl}, status = #{status}, remark = #{remark}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT i.*, c.customer_name
FROM invoice i
LEFT JOIN customer c ON i.customer_id = c.id

    AND i.company_id = #{companyId}
    AND i.customer_id = #{customerId}
    AND i.order_id = #{orderId}
    AND i.status = #{status}

ORDER BY i.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM invoice

    AND company_id = #{companyId}
    AND customer_id = #{customerId}
    AND order_id = #{orderId}
    AND status = #{status}
